d }, playerinfo = { action = function(a) if not a[1] then return "ERROR|Usage: playerinfo <name>" end local p=game.Players:FindFirstChild(a[1]) if not p then return "ERROR|Not found" end return "Name: "..p.Name.."\nID: "..p.UserId.."\nAge: "..p.AccountAge.." days" end }, npcs = { action = function() local l={} for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("Model") then local h=v:FindFirstChildOfClass("Humanoid") if h and not game.Players:GetPlayerFromCharacter(v) then table.insert(l,v.Name.." | HP: "..math.floor(h.Health)) end end end return table.concat(l,"\n") end }, lights = { action = function() local l={} for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("Light") then table.insert(l,v.ClassName.." | "..v:GetFullName()) end end return table.concat(l,"\n") end }, effects = { action = function() local l={} for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("ParticleEmitter") or v:IsA("Fire") or v:IsA("Smoke") then table.insert(l,v.ClassName.." | "..v:GetFullName()) end end return table.concat(l,"\n") end }, terraininfo = { action = function() local t=workspace:FindFirstChildOfClass("Terrain") if not t then return "No Terrain" end return "Size: "..tostring(t.Size) end }, near = { action = function(a) local r=tonumber(a[1])or 20 local lp=game.Players.LocalPlayer local c=lp.Character local h=c and c:FindFirstChild("HumanoidRootPart") if not h then return "ERROR|No char" end local l={} for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("BasePart") and v~=h then local d=(v.Position-h.Position).Magnitude if d<=r then table.insert(l,string.format("%.1f | %s | %s",d,v.ClassName,v:GetFullName())) end end end return table.concat(l,"\n") end }, modelinfo = { action = function(a) if not a[1] then return "ERROR|Usage: modelinfo <name>" end for _,v in ipairs(workspace:GetDescendants()) do if v:IsA("Model") and (v.Name==a[1] or v:GetFullName():find(a[1])) then local p,m=0,0 for _,c in ipairs(v:GetDescendants()) do if c:IsA("BasePart") then p=p+1